 # A cancellation is a real paid choice; rebook through the ordinary calendar.
 board();p.locator('[data-gathering-cancel]').click();confirm();assert state()['civicCalendar']['events'][0]['status']=='cancelled';paid_cancel=state()['treasury'];p.locator('[data-gathering-review="'+str(venue)+'"]').click();p.locator('#gatheringStart').fill(str(start));confirm();second=state()['civicCalendar']['events'][-1];assert paid_cancel-state()['treasury']==second['paid'];p.evaluate('__townTest.step(2)');active=state()['civicCalendar']['events'][-1];assert active['status']=='active' and active['daily'][0]['attendance']>0
 frozen=p.evaluate('__townTest.save()');p.evaluate('__calendarJourney.callback();__calendarJourney.callback()');assert p.evaluate('__townTest.save()')==frozen
 assert p.evaluate('s=>__townTest.load(s)',frozen);restored=p.evaluate('__townTest.save()');assert state()['civicCalendar']['events'][-1]==active;p.evaluate('__calendarJourney.callback()');assert p.evaluate('__townTest.save()')==restored
 p.evaluate('__townTest.step(2)');complete=state()['civicCalendar']['events'][-1];assert complete['status']=='complete';end=p.evaluate('__townTest.save()');assert p.evaluate('s=>__townTest.load(s)',end);p.evaluate('__calendarJourney.callback()');assert state()['civicCalendar']['events'][-1]==complete
 board();assert 'Founders Commons' in p.locator('#civicCalendar').inner_text();assert state()['publicPlaces']['places'][0]['name']=='Founders Commons'
 # Pay another preparation, then actually clear the public square before opening.
 p.locator('[data-gathering-review="'+str(venue)+'"]').click();p.locator('#gatheringStart').fill(str(state()['day']+3));confirm();p.evaluate('(v)=>__calendarJourney.capture(v,__townTest.get().day+6)',venue)
 p.locator('[data-inspect="'+str(venue)+'"]').click();clear=p.locator('[data-urban-clear="'+str(venue)+'"]');clear.click();confirm();assert not p.evaluate('v=>__calendarJourney.venue(v)',venue);before_expired=p.evaluate('__townTest.save()');assert not p.evaluate('__expiredVenueAuthorize().ok');assert p.evaluate('__townTest.save()')==before_expired;assert not p.evaluate('__calendarJourney.cues().length');p.evaluate('__townTest.step(3)');failed=state()['civicCalendar']['events'][-1];assert failed['status']=='failed'and failed['paid']==failed['cost'];assert not failed['daily'];assert p.evaluate('__townTest.validate().ok');failed_save=p.evaluate('__townTest.save()');assert p.evaluate('s=>__townTest.load(s)',failed_save);assert state()['civicCalendar']['events'][-1]==failed;assert not p.evaluate('__calendarJourney.cues().length')
 board();out=ROOT/'reports/civic-calendar-journey';out.mkdir(parents=True,exist_ok=True);p.locator('#civicCalendar .entry').filter(has_text='failed').last.scroll_into_view_if_needed();p.screenshot(path=str(out/'lost-venue-calendar.png'));history=p.locator('#civicCalendar').inner_text();assert 'Visit the recorded site' in history and 'original venue is gone' in history
 # New-town reset uses the actual Options confirmation and founding flow.
 panel('settings');p.locator('#restart').click();p.locator('[data-event-choice="1"]').click();assert state().get('civicCalendar')is None;assert not p.evaluate('__calendarJourney.cues().length');new_cash=state()['treasury'];assert not p.evaluate('__expiredVenueAuthorize().ok');assert state()['treasury']==new_cash;assert not errors,errors
 (out/'controls.json').write_text(json.dumps({'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'openingTreasury':opening['treasury'],'ordinaryReceiptsTreasury':earned['treasury'],'review':text,'cancelledPreparation':event,'activeGathering':active,'completedGathering':complete,'failedDemolishedVenue':failed,'calendarHistoryText':history,'newTownClearsCalendar':True,'duplicateCanonicalCallbacksNoMutation':True,'cooperativePrototype':'not present/enabled on base; canonical repeated-commit callback exercised','errors':errors},indent=2)+'\n');b.close()
